Запишите число, которое будет напечатано в результате выполнения программы: 
s = 0
for i in range(1, 11):
    if i % 2 == 0:
        s = s + i
print(s)

Определите, что будет напечатано в результате работы программы: 
var s, n: integer;
begin
s := 0;
n := 0;
while s < 100 do
begin
s := s + 10;
n := n + 2;
end;
writeln(n)
end.
